import chess
import chess.pgn
import io
import json

def repair_game(pgn_text, game_id):
    """Analyze and repair a corrupted PGN game."""
    errors_found = []

    # Parse the original PGN
    original_pgn = pgn_text.strip()

    # Try to parse and identify errors
    lines = pgn_text.strip().split('\n')
    headers = []
    moves_text = []
    in_headers = True
    for line in lines:
        line = line.strip()
        if line.startswith('['):
            headers.append(line)
        elif line == '':
            if headers:
                in_headers = False
            moves_text.append(line)
        else:
            in_headers = False
            moves_text.append(line)

    moves_str = ' '.join(moves_text)
    # Remove result codes from moves
    result_codes = ['1-0', '0-1', '1/2-1/2', '*']
    for rc in result_codes:
        moves_str = moves_str.replace(rc, '')
    moves_str = moves_str.strip()

    # Split into individual move tokens
    tokens = moves_str.split()

    # Try to play through the game and fix errors
    board = chess.Board()
    repaired_moves = []
    move_numbers = []

    i = 0
    current_move_num = 0
    is_white = True

    while i < len(tokens):
        token = tokens[i]

        # Skip move numbers like "1.", "2.", etc.
        if token.endswith('.') and token[:-1].isdigit():
            expected_num = int(token[:-1])
            if expected_num != current_move_num + 1:
                current_move_num = expected_num - 1
            i += 1
            continue

        # Try to parse the move
        try:
            move = board.parse_san(token)
            board.push(move)
            repaired_moves.append(token)
            if is_white:
                current_move_num += 1
                move_numbers.append(current_move_num)
            else:
                move_numbers.append(current_move_num)
            is_white = not is_white
            i += 1
        except:
            # Move is illegal - try to fix it
            fixed = try_fix_move(board, token, game_id, len(repaired_moves))
            if fixed:
                move_num_str = f"{current_move_num + 1}" if is_white else ""
                errors_found.append(f"illegal move at {move_num_str}.{token}")
                board.push(fixed["move"])
                repaired_moves.append(fixed["notation"])
                if is_white:
                    current_move_num += 1
                    move_numbers.append(current_move_num)
                else:
                    move_numbers.append(current_move_num)
                is_white = not is_white
                i += 1
            else:
                errors_found.append(f"unfixable move at {token}")
                i += 1

    # Build repaired PGN
    repaired_pgn_lines = headers.copy()
    repaired_pgn_lines.append("")

    # Reconstruct move list with proper numbering
    move_list = []
    for idx, move in enumerate(repaired_moves):
        if idx % 2 == 0:
            move_num = idx // 2 + 1
            move_list.append(f"{move_num}. {move}")
        else:
            move_list.append(move)

    # Add result
    result = board.result()
    if result == '*':
        # Try to find original result
        for line in lines:
            if '[Result' in line:
                result = line.split('"')[1]
                break

    move_list.append(result)
    repaired_pgn_lines.append(' '.join(move_list))
    repaired_pgn = '\n'.join(repaired_pgn_lines)

    # Find critical position
    critical = find_critical_position(board, repaired_moves)

    return {
        "game_id": game_id,
        "original_pgn": original_pgn,
        "repaired_pgn": repaired_pgn,
        "errors_found": errors_found,
        "critical_position": critical
    }

def try_fix_move(board, token, game_id, move_index):
    """Try to fix an illegal move."""
    # Parse the piece and destination
    piece_char = token[0]

    # Get piece type
    piece_map = {'K': chess.KING, 'Q': chess.QUEEN, 'R': chess.ROOK, 
                 'B': chess.BISHOP, 'N': chess.KNIGHT, 'P': chess.PAWN}

    if piece_char not in piece_map:
        # Pawn move
        return try_fix_pawn_move(board, token)

    piece_type = piece_map[piece_char]

    # Find all legal moves for this piece type
    for move in board.legal_moves:
        if board.piece_at(move.from_square).piece_type != piece_type:
            continue

        # Check if SAN matches (approximately)
        san = board.san(move)
        # Compare destination squares
        if len(token) >= 2:
            dest_file = token[-2] if token[-2].isalpha() else None
            dest_rank = token[-1] if token[-1].isdigit() else None
            move_dest_file = chess.square_name(move.to_square)[-1]
            move_dest_rank = chess.square_name(move.to_square)[-2]

            # Try to find closest match
            if dest_file and dest_rank:
                # Fix rank errors (like f9 -> f8)
                if dest_file == move_dest_file:
                    if dest_rank.isdigit() and abs(int(dest_rank) - int(move_dest_rank)) <= 2:
                        return {"move": move, "notation": san}
                # Fix file errors
                if dest_rank == move_dest_rank:
                    if abs(ord(dest_file) - ord(move_dest_file)) <= 2:
                        return {"move": move, "notation": san}

    return None

def try_fix_pawn_move(board, token):
    """Try to fix an illegal pawn move."""
    for move in board.legal_moves:
        if board.piece_at(move.from_square).piece_type != chess.PAWN:
            continue
        san = board.san(move)
        dest = chess.square_name(move.to_square)
        orig_dest = token[-2:] if len(token) >= 2 else ""

        if len(orig_dest) == 2 and orig_dest[0].isalpha() and orig_dest[1].isdigit():
            if dest[0] == orig_dest[0] and abs(int(dest[1]) - int(orig_dest[1])) <= 2:
                return {"move": move, "notation": san}
            if abs(ord(dest[0]) - ord(orig_dest[0])) <= 1 and dest[1] == orig_dest[1]:
                return {"move": move, "notation": san}
    return None

def find_critical_position(board, moves):
    """Find the critical position in the game."""
    # Analyze final position
    final_eval = evaluate_position(board)
    return {"move_number": len(moves), "evaluation": final_eval}

def evaluate_position(board):
    """Simple evaluation of the position."""
    if board.is_checkmate():
        if board.turn == chess.WHITE:
            return "+M"
        else:
            return "-M"
    if board.is_stalemate():
        return "0.0"

    # Material evaluation
    material = {
        chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3,
        chess.ROOK: 5, chess.QUEEN: 9
    }
    score = 0
    for sq in chess.SQUARES:
        piece = board.piece_at(sq)
        if piece:
            val = material.get(piece.piece_type, 0)
            score += val if piece.color == chess.WHITE else -val

    return f"+{score}" if score >= 0 else str(score)

def solve_puzzle(puzzle):
    """Solve a chess puzzle."""
    board = chess.Board(puzzle["fen"])
    desc = puzzle.get("description", "")

    # Check for mate in N
    mate_in = None
    if "mate in" in desc.lower():
        try:
            mate_in = int(desc.split("mate in")[1].strip())
        except:
            pass

    if mate_in and mate_in <= 4:
        return solve_mate_in(board, mate_in, puzzle["id"])
    else:
        return find_best_move(board, puzzle["id"])

def solve_mate_in(board, depth, puzzle_id):
    """Find mate in N moves."""
    solution = find_mate_sequence(board, depth, [])
    if solution:
        return {
            "puzzle_id": puzzle_id,
            "best_move": solution[0],
            "continuation": solution,
            "mate_in": len(solution) // 2 + (1 if len(solution) % 2 else 0)
        }
    # Fallback
    best = find_best_move(board, puzzle_id)
    return best

def find_mate_sequence(board, max_depth, moves):
    """Recursively find a mating sequence."""
    if max_depth <= 0:
        return None

    if not board.is_checkmate():
        for move in board.legal_moves:
            board.push(move)
            san = board.san(move)
            if board.is_checkmate():
                return moves + [san]

            # Check opponent's responses
            has_non_mate_response = False
            best_response = None
            for response in board.legal_moves:
                board.push(response)
                result = find_mate_sequence(board, max_depth - 1, moves + [san])
                board.pop()
                if result:
                    return result + [board.san(response)] if False else result
                has_non_mate_response = True
            board.pop()

    return None

def find_best_move(board, puzzle_id):
    """Find the best move using simple analysis."""
    best_move = None
    best_score = -9999

    for move in board.legal_moves:
        board.push(move)
