import chess
import chess.pgn
import io
import json

def split_pgn_games(pgn_content):
    """Split PGN content into individual games."""
    games = []
    current_lines = []

    for line in pgn_content.split('\n'):
        if line.strip() == '' and current_lines:
            # Check if we've seen moves already
            has_moves = any(not l.strip().startswith('[') and l.strip() != '' for l in current_lines)
            if has_moves:
                games.append('\n'.join(current_lines))
                current_lines = []
            else:
                current_lines.append(line)
        else:
            current_lines.append(line)

    if current_lines and any(l.strip() for l in current_lines):
        games.append('\n'.join(current_lines))

    return games

def repair_game(pgn_text, game_id):
    """Analyze and repair a corrupted PGN game."""
    errors_found = []
    original_pgn = pgn_text.strip()

    # Parse headers and moves
    lines = pgn_text.strip().split('\n')
    headers = []
    moves_text = []
    found_moves = False

    for line in lines:
        stripped = line.strip()
        if stripped.startswith('['):
            headers.append(stripped)
        elif stripped == '' and not found_moves:
            continue
        elif stripped == '' and found_moves:
            continue
        else:
            found_moves = True
            moves_text.append(stripped)

    moves_str = ' '.join(moves_text)
    # Remove result codes
    for rc in ['1-0', '0-1', '1/2-1/2', '*']:
        moves_str = moves_str.replace(rc, '')
    moves_str = moves_str.strip()

    tokens = moves_str.split()

    board = chess.Board()
    repaired_moves = []
    current_move_num = 0
    is_white = True

    i = 0
    while i < len(tokens):
        token = tokens[i]

        # Skip move numbers like "1.", "2.", etc.
        if token.endswith('.') and token[:-1].isdigit():
            i += 1
            continue

        try:
            move = board.parse_san(token)
            san = board.san(move)
            board.push(move)
            repaired_moves.append(san)
            if is_white:
                current_move_num += 1
            is_white = not is_white
            i += 1
        except:
            move_num_label = f"{current_move_num + 1}." if is_white else f"{current_move_num}..."
            fixed = try_fix_move(board, token)
            if fixed:
                errors_found.append(f"illegal move at {move_num_label}{token}")
                board.push(fixed["move"])
                repaired_moves.append(fixed["notation"])
                if is_white:
                    current_move_num += 1
                is_white = not is_white
                i += 1
            else:
                errors_found.append(f"unfixable move {token}")
                i += 1

    # Build repaired PGN
    repaired_lines = headers.copy()
    repaired_lines.append("")

    move_list = []
    for idx, move in enumerate(repaired_moves):
        if idx % 2 == 0:
            move_list.append(f"{idx//2 + 1}. {move}")
        else:
            move_list.append(move)

    final_result = board.result()
    if final_result == '*':
        # Use original result
        for h in headers:
            if h.startswith('[Result'):
                final_result = h.split('"')[1]
                break
        if final_result == '*':
            final_result = '1-0'
    move_list.append(final_result)
    repaired_lines.append(' '.join(move_list))
    repaired_pgn = '\n'.join(repaired_lines)

    critical = find_critical_position(board, len(repaired_moves))

    return {
        "game_id": game_id,
        "original_pgn": original_pgn,
        "repaired_pgn": repaired_pgn,
        "errors_found": errors_found,
        "critical_position": critical
    }

def try_fix_move(board, token):
    """Try to fix an illegal move by finding closest legal move."""
    piece_char = token[0]
    piece_map = {'K': chess.KING, 'Q': chess.QUEEN, 'R': chess.ROOK, 
                 'B': chess.BISHOP, 'N': chess.KNIGHT}

    is_pawn = piece_char not in piece_map and piece_char.isalpha()

    best_match = None
    best_dist = 999

    for move in board.legal_moves:
        piece = board.piece_at(move.from_square)
        if not piece:
            continue

        if is_pawn:
            if piece.piece_type != chess.PAWN:
                continue
        else:
            if piece.piece_type != piece_map.get(piece_char):
                continue

        san = board.san(move)
        dist = move_distance(token, san)
        if dist < best_dist:
            best_dist = dist
            best_match = {"move": move, "notation": san}

    return best_match

def move_distance(token1, token2):
    """Calculate similarity between two move notations."""
    dest1 = token1[-2:] if len(token1) >= 2 else ""
    dest2 = token2[-2:] if len(token2) >= 2 else ""

    if len(dest1) == 2 and len(dest2) == 2:
        f1, f2 = dest1[0], dest2[0]
        r1, r2 = dest1[1], dest2[1]
        if f1.isalpha() and f2.isalpha() and r1.isdigit() and r2.isdigit():
            file_dist = abs(ord(f1) - ord(f2))
            rank_dist = abs(int(r1) - int(r2))
            return file_dist + rank_dist
    return 999

def find_critical_position(board, move_count):
    """Find the critical position."""
    if board.is_checkmate():
        return {"move_number": move_count, "evaluation": "checkmate"}
    if board.is_stalemate():
        return {"move_number": move_count, "evaluation": "stalemate"}

    material = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
    score = 0
    for sq in chess.SQUARES:
        piece = board.piece_at(sq)
        if piece:
            val = material.get(piece.piece_type, 0)
            score += val if piece.color == chess.WHITE else -val

    eval_str = f"+{score}" if score >= 0 else str(score)
    return {"move_number": move_count, "evaluation": eval_str}

def solve_puzzle(puzzle):
    """Solve a chess puzzle."""
    board = chess.Board(puzzle["fen"])
    desc = puzzle.get("description", "").lower()

    mate_in_target = None
    if "mate in" in desc:
        try:
            mate_in_target = int(desc.split("mate in")[1].strip())
        except:
            pass

    result = {"puzzle_id": puzzle["id"]}

    if mate_in_target and mate_in_target <= 4:
        solution = find_mate_in_n(board, mate_in_target)
        if solution:
            result["best_move"] = solution[0]
            result["continuation"] = solution
            result["mate_in"] = len(solution)
            return result

    # Find best move by material gain
    best_move = None
    best_score = -9999
    best_san = None

    for move in board.legal_moves:
        san = board.san(move)
        board.push(move)
        score = evaluate_move(board, move)
        board.pop()
        if score > best_score:
            best_score = score
            best_move = move
            best_san = san

    if best_move:
        result["best_move"] = best_san
        result["continuation"] = [best_san]
        result["mate_in"] = None
    else:
        result["best_move"] = None
        result["continuation"] = []
        result["mate_in"] = None

    return result

def evaluate_move(board, move):
    """Evaluate a move's quality."""
    score = 0
    piece_values = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900}

    if board.is_capture(move):
        captured = board.piece_at(move.to_square)
        if captured:
            score += piece_values.get(captured.piece_type, 0)

    if board.is_check():
        score += 50
    if board.is_checkmate():
        score += 10000

    return score

def find_mate_in_n(board, n):
    """Find mate in n halfmoves (plies)."""
    if board.is_checkmate():
        return []

    if n <= 0:
        return None

    for move in board.legal_moves:
        san = board.san(move)
        board.push(move)

        if board.is_checkmate():
            board.pop()
            return [san]

        # All opponent responses must lead to mate in n-2 more plies
        all_lead_to_mate = True
        continuation = None

        for response in board.legal_moves:
            board.push(response)
            rest = find_mate_in_n(board, n - 2)
            board.pop()
            if rest is None:
                all_lead_to_mate = False
                break
            resp_san = board.san(response)
            if continuation is None:
                continuation = [resp_san] + rest

        if all_lead_to_mate and continuation:
            board.pop()
            return [san] + continuation

        board.pop()

    return None

def main():
    with open("/workdir/data/games.pgn") as f:
        pgn_content = f.read()

    with open("/workdir/data/puzzles.json") as f:
        puzzles = json.load(f)

    games = split_pgn_games(pgn_content)

    repaired_games = []
    total_errors = 0

    for idx, game_text in enumerate(games):
        if not game_text.strip():
            continue
        result = repair_game(game_text, idx + 1)
        repaired_games.append(result)
        total_errors += len(result["errors_found"])

    puzzle_solutions = []
    for puzzle in puzzles:
        sol = solve_puzzle(puzzle)
        puzzle_solutions.append(sol)

    output = {
        "repaired_games": repaired_games,
        "puzzle_solutions": puzzle_solutions,
        "analysis_summary": {
            "games_processed": len(repaired_games),
            "errors_fixed": total_errors,
            "puzzles_solved": len(puzzle_solutions)
        }
    }

    with open("/workdir/chess_analysis.json", "w") as f:
        json.dump(output, f, indent=2)

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
