def try_fix_move(board, token):
    """Try to fix an illegal move by finding closest legal move."""
    piece_char = token[0]
    piece_map = {'K': chess.KING, 'Q': chess.QUEEN, 'R': chess.ROOK, 
                 'B': chess.BISHOP, 'N': chess.KNIGHT}

    is_pawn = piece_char not in piece_map and piece_char.isalpha()

    best_match = None
    best_dist = 999

    for move in board.legal_moves:
        piece = board.piece_at(move.from_square)
        if not piece:
            continue

        if is_pawn:
            if piece.piece_type != chess.PAWN:
                continue
        else:
            if piece.piece_type != piece_map.get(piece_char):
                continue

        san = board.san(move)
        dist = move_distance(token, san)
        if dist < best_dist:
            best_dist = dist
            best_match = {"move": move, "notation": san}

    return best_match

def move_distance(token1, token2):
    """Calculate similarity between two move notations."""
    dest1 = token1[-2:] if len(token1) >= 2 else ""
    dest2 = token2[-2:] if len(token2) >= 2 else ""

    if len(dest1) == 2 and len(dest2) == 2:
        f1, f2 = dest1[0], dest2[0]
        r1, r2 = dest1[1], dest2[1]
        if f1.isalpha() and f2.isalpha() and r1.isdigit() and r2.isdigit():
            file_dist = abs(ord(f1) - ord(f2))
            rank_dist = abs(int(r1) - int(r2))
            return file_dist + rank_dist
    return 999

def find_critical_position(board, move_count):
    """Find the critical position."""
    if board.is_checkmate():
        return {"move_number": move_count, "evaluation": "checkmate"}
    if board.is_stalemate():
        return {"move_number": move_count, "evaluation": "stalemate"}

    material = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
    score = 0
    for sq in chess.SQUARES:
        piece = board.piece_at(sq)
        if piece:
            val = material.get(piece.piece_type, 0)
            score += val if piece.color == chess.WHITE else -val

    eval_str = f"+{score}" if score >= 0 else str(score)
    return {"move_number": move_count, "evaluation": eval_str}

def solve_puzzle(puzzle):
    """Solve a chess puzzle."""
    board = chess.Board(puzzle["fen"])
    desc = puzzle.get("description", "").lower()

    mate_in_target = None
    if "mate in" in desc:
        try:
            mate_in_target = int(desc.split("mate in")[1].strip())
        except:
            pass

    result = {"puzzle_id": puzzle["id"]}

