    if mate_in_target and mate_in_target <= 4:
        solution = find_mate_in_n(board, mate_in_target)
        if solution:
            result["best_move"] = solution[0]
            result["continuation"] = solution
            result["mate_in"] = len(solution)
            return result

    # Try any mate up to depth 4
    for depth in range(1, 5):
        solution = find_mate_in_n(board, depth)
        if solution:
            result["best_move"] = solution[0]
            result["continuation"] = solution
            result["mate_in"] = len(solution)
            return result

    # Find best move by material gain
    best_move = None
    best_score = -9999
    best_san = None

    for move in board.legal_moves:
        san = board.san(move)
        score = evaluate_move_before_push(board, move)
        board.push(move)
        if board.is_check():
            score += 50
        if board.is_checkmate():
            score += 10000
        board.pop()
        if score > best_score:
            best_score = score
            best_move = move
            best_san = san

    if best_move:
        result["best_move"] = best_san
        result["continuation"] = [best_san]
        result["mate_in"] = None
    else:
        result["best_move"] = None
        result["continuation"] = []
        result["mate_in"] = None

    return result

def evaluate_move_before_push(board, move):
    """Evaluate a move's quality before pushing."""
    score = 0
    piece_values = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900}

    captured = board.piece_at(move.to_square)
    if captured and captured.color != board.turn:
        score += piece_values.get(captured.piece_type, 0)

    return score

def find_mate_in_n(board, max_depth):
    """Find mate in at most max_depth moves (full moves, not plies)."""
    # max_depth is in full moves, so we need 2*max_depth plies
    max_plies = 2 * max_depth
    return _find_mate(board, max_plies, board.turn, [])

def _find_mate(board, remaining_plies, attacker, path):
    """Recursively find mating sequence."""
    if board.is_checkmate():
        return list(path)

    if board.is_stalemate() or board.is_insufficient_material():
        return None

    if remaining_plies <= 0:
        return None

    if board.turn == attacker:
        # Attacker's turn - find a move leading to forced mate
        for move in board.legal_moves:
            san = board.san(move)
            board.push(move)
            result = _find_mate(board, remaining_plies - 1, attacker, path + [san])
            board.pop()
            if result is not None:
                return result
    else:
        # Defender's turn - ALL moves must lead to mate
        continuations = []
        for response in board.legal_moves:
            san = board.san(response)
            board.push(response)
            result = _find_mate(board, remaining_plies - 1, attacker, path + [san])
            board.pop()
            if result is None:
                return None
            continuations.append(result)
        if continuations:
            return continuations[0]

    return None

def main():
    with open("/workdir/data/games.pgn") as f:
        pgn_content = f.read()

    with open("/workdir/data/puzzles.json") as f:
        puzzles = json.load(f)

    games = split_pgn_games(pgn_content)

    repaired_games = []
    total_errors = 0

    for idx, game_text in enumerate(games):
        if not game_text.strip():
