        if f1.isalpha() and f2.isalpha() and r1.isdigit() and r2.isdigit():
            return abs(ord(f1) - ord(f2)) + abs(int(r1) - int(r2))
    return 999

def find_critical_position(board, move_count):
    if board.is_checkmate():
        return {"move_number": move_count, "evaluation": "checkmate"}
    if board.is_stalemate():
        return {"move_number": move_count, "evaluation": "stalemate"}
    material = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
    score = 0
    for sq in chess.SQUARES:
        piece = board.piece_at(sq)
        if piece:
            val = material.get(piece.piece_type, 0)
            score += val if piece.color == chess.WHITE else -val
    eval_str = f"+{score}" if score >= 0 else str(score)
    return {"move_number": move_count, "evaluation": eval_str}

def solve_puzzle(puzzle):
    board = chess.Board(puzzle["fen"])
    desc = puzzle.get("description", "").lower()

    mate_in_target = None
    if "mate in" in desc:
        try:
            mate_in_target = int(desc.split("mate in")[1].strip())
        except:
            pass

    result = {"puzzle_id": puzzle["id"]}

    # Try mate search with limited depth
    if mate_in_target:
        solution = find_mate_limited(board, mate_in_target)
        if solution:
            result["best_move"] = solution[0]
            result["continuation"] = solution
            result["mate_in"] = len(solution)
            return result

    # Try mate in 1-3
    for depth in range(1, 4):
        solution = find_mate_limited(board, depth)
        if solution:
            result["best_move"] = solution[0]
            result["continuation"] = solution
            result["mate_in"] = len(solution)
            return result

    # Find best move
    best_move = None
    best_score = -9999
    best_san = None

    for move in board.legal_moves:
        san = board.san(move)
        score = evaluate_move_before_push(board, move)
        board.push(move)
        if board.is_check():
            score += 50
        if board.is_checkmate():
            score += 10000
        board.pop()
        if score > best_score:
            best_score = score
            best_move = move
            best_san = san

    if best_move:
        result["best_move"] = best_san
        result["continuation"] = [best_san]
        result["mate_in"] = None
    else:
        result["best_move"] = None
        result["continuation"] = []
        result["mate_in"] = None

    return result

def evaluate_move_before_push(board, move):
    score = 0
    piece_values = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900}
    captured = board.piece_at(move.to_square)
    if captured and captured.color != board.turn:
        score += piece_values.get(captured.piece_type, 0)
    return score

def find_mate_limited(board, max_moves):
    """Find mate in max_moves full moves with node limit."""
    _find_mate.count = 0
    _find_mate.limit = 100000
    max_plies = 2 * max_moves
    result = _find_mate(board, max_plies, board.turn, [])
    return result

def _find_mate(board, remaining, attacker, path):
    _find_mate.count += 1
    if _find_mate.count > _find_mate.limit:
        return None

    if board.is_checkmate():
        return list(path)
    if board.is_stalemate() or board.is_insufficient_material():
        return None
    if remaining <= 0:
        return None

    if board.turn == attacker:
        moves = list(board.legal_moves)
        checks = [m for m in moves if board.gives_check(m)]
        others = [m for m in moves if not board.gives_check(m)]
        ordered = checks + others

        for move in ordered:
            san = board.san(move)
            board.push(move)
            result = _find_mate(board, remaining - 1, attacker, path + [san])
            board.pop()
            if result is not None:
                return result
    else:
        continuations = []
        for response in board.legal_moves:
            san = board.san(response)
            board.push(response)
            result = _find_mate(board, remaining - 1, attacker, path + [san])
            board.pop()
            if result is None:
                return None
            continuations.append(result)
        if continuations:
            return continuations[0]
    return None

def main():
    with open("/workdir/data/games.pgn") as f:
        pgn_content = f.read()
    with open("/workdir/data/puzzles.json") as f:
        puzzles = json.load(f)

    games = split_pgn_games(pgn_content)
    repaired_games = []
    total_errors = 0

    for idx, game_text in enumerate(games):
        if not game_text.strip():
            continue
        result = repair_game(game_text, idx + 1)
        repaired_games.append(result)
        total_errors += len(result["errors_found"])

    puzzle_solutions = []
    for puzzle in puzzles:
        sol = solve_puzzle(puzzle)
        puzzle_solutions.append(sol)

    output = {
        "repaired_games": repaired_games,
        "puzzle_solutions": puzzle_solutions,
        "analysis_summary": {
            "games_processed": len(repaired_games),
            "errors_fixed": total_errors,
            "puzzles_solved": len(puzzle_solutions)
        }
    }

    with open("/workdir/chess_analysis.json", "w") as f:
        json.dump(output, f, indent=2)
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
